// NIOGEN | n8n/cadencia/c02_interruptor.js — nó "2 · Interruptor" do mari_cadencia (04/11/2026)
// Kill switch e modo da cadência (staticData). Padrão: DESLIGADA e em modo 'teste'.
//   _cadenciaAtiva  false | true      → false = a rodada para aqui (nada é lido nem enviado)
//   _modoCadencia   'teste' | 'chatwoot'
//       teste    → só conversas canal 'teste' (rota /webhook/mari-teste); envio SIMULADO (grava turno + toque)
//       chatwoot → só conversas canal 'whatsapp'; envio real pela API do Chatwoot (nós 6g/7 hoje desligados)
// Comandos pela rota admin (header X-Mari-Secret): ligar | desligar | modo teste | modo chatwoot | status
// Sem texto de negócio e sem segredo.

const sd = $getWorkflowStaticData('global');
if (sd._cadenciaAtiva === undefined) sd._cadenciaAtiva = false;
if (!sd._modoCadencia) sd._modoCadencia = 'teste';

const ex = (n) => { try { return $(n).isExecuted; } catch (e) { return false; } };
const estado = () => ({ ativa: sd._cadenciaAtiva, modo: sd._modoCadencia, ultima_rodada: sd._ultimaRodada || null });

if (ex('1w · Admin cadência')) {
  const body = $('1w · Admin cadência').first().json.body || {};
  const cmd = String(body.admin || '').toLowerCase().trim();
  if (cmd === 'ligar') sd._cadenciaAtiva = true;
  else if (cmd === 'desligar') sd._cadenciaAtiva = false;
  else if (cmd === 'modo teste' || cmd === 'modo chatwoot') sd._modoCadencia = cmd.split(' ')[1];
  else if (cmd !== 'status') return [{ json: { admin: true, resposta: { erro: 'use: ligar | desligar | modo teste | modo chatwoot | status' } } }];
  return [{ json: { admin: true, resposta: { admin: true, ...estado() } } }];
}

if (!sd._cadenciaAtiva) return [];   // kill switch: nada roda

sd._ultimaRodada = new Date().toISOString();
return [{ json: {
  admin: false,
  modo: sd._modoCadencia,
  canal: sd._modoCadencia === 'chatwoot' ? 'whatsapp' : 'teste',
  agora: sd._ultimaRodada,
  limite: 30,
} }];

// NIOGEN | n8n/cadencia/c03_itens.js — nó "3b · Itens" do mari_cadencia (04/11/2026)
// A RPC mari_cadencia_candidatos devolve um array de objetos (cada um já com a decisão do banco:
// passo, ação, texto, template, params). Aqui só vira um item por conversa — sem decisão nenhuma.
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const lista = Array.isArray(j) ? j : (j && j.conversa_id ? [j] : []);
  for (const c of lista) {
    const v = (c && c.mari_cadencia_candidatos) || c;   // PostgREST pode embrulhar setof jsonb no nome da função
    if (v && v.conversa_id && v.pode_enviar === true) out.push({ json: v });
  }
}
return out.slice(0, 30);   // teto por rodada (o banco já limita; aqui é cinto + suspensório)

// 0142: pedido ao Claude para a Mari escrever a cutucada (só texto; o filtro fica no 4e).
const c = $('4 · Um por vez').first().json;
const ctx = $input.first().json || {};
const sistema = `Você é a Mari, vendedora da Nio Internet (fibra) no WhatsApp. O cliente parou de responder e você vai mandar uma
CUTUCADA para trazê-lo de volta — curta, simpática e persuasiva, como uma boa vendedora que quer muito fechar com ele.
Regras (todas obrigatórias):
- No máximo 2 frases e 180 caracteres. Português do Brasil, natural, sem formalidade. No máximo 1 emoji.
- Termine com UMA pergunta fácil de responder, que puxe o próximo passo do que FALTA (CEP, número, operadora, escolher o plano, nome/CPF, e-mail, forma de pagamento, conferir os dados).
- Use o primeiro nome do cliente se vier no contexto. Pode citar a cidade e o plano escolhido.
- Um argumento por vez, só do que é verdade: preço fixo até 2030; roteador Wi-Fi incluído; atendimento rápido por aqui; é rapidinho (1–2 minutos).
- NUNCA: desconto, brinde, promoção, "última chance", "só hoje", prazo ou data de instalação, valor em R$, "cobertura confirmada", asterisco, nome de empresa que não seja Nio.
- Não repita nenhuma cutucada já enviada (lista no contexto) nem comece igual a elas. Não peça desculpa por insistir.
- Cutucada 5 é a última da janela: leve, sem pressão (ex.: deixar o atendimento separado e perguntar se quer seguir).
Responda SÓ com o texto da mensagem, sem aspas.`;
const pedido = {
  model: 'claude-sonnet-5-5', max_tokens: 400,
  output_config: { effort: 'low' },
  system: sistema,
  messages: [{ role: 'user', content: 'Contexto da conversa (JSON):\n' + JSON.stringify(ctx) }],
};
return [{ json: { pedido } }];

// 0142: filtro da cutucada escrita pela Mari. Reprovou (ou a API falhou) → texto de reserva do banco. Sai o candidato do
// "4 · Um por vez" com o texto final — o 5 · Montar envio segue igual.
const c = { ...$('4 · Um por vez').first().json };
const r = $input.first().json || {};
let ctx = {};
try { ctx = $('4b · Supabase contexto').first().json || {}; } catch (e) { ctx = {}; }
const blocos = Array.isArray(r.content) ? r.content.filter((x) => x && x.type === 'text') : [];
let t = blocos.map((x) => x.text || '').join(' ').replace(/\s+/g, ' ').trim().replace(/^["“']|["”']$/g, '');
const norm = (x) => String(x || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const n = norm(t);
const ja = (Array.isArray(ctx.cutucadas_ja_enviadas) ? ctx.cutucadas_ja_enviadas : []).map(norm);
const ruim = !t || t.length < 12 || t.length > 260 || !t.includes('?') || t.includes('*') || /r\$\s*\d/.test(n)
  || /descont|gratis|gratuit|promo|brinde|ultima chance|so hoje|somente hoje|amanha|instala(cao|r)? (hoje|amanha|em )|prazo|cobertura confirmada|garanto|garantimos|combo|pacote|dh\x61rma|2028/.test(n)
  || ja.some((x) => x && (x === n || x.slice(0, 25) === n.slice(0, 25)))
  || r.stop_reason === 'refusal' || !!r.error;
if (!ruim) c.texto = t;
c.cutucada_ia = !ruim;
return [{ json: c }];

// NIOGEN | n8n/cadencia/c05_montar.js — nó "5 · Montar envio" do mari_cadencia (04/11/2026)
// Recebe UM candidato (loop de 1) e monta o corpo da mensagem para a API do Chatwoot:
//   texto livre (dentro da janela de 24 h) → { content, message_type, private:false }
//   template (fora da janela)              → { content: corpo renderizado, template_params: { name, category,
//                                              language, processed_params: { body: { "1": …, "2": … } } } }
// (formato do noF4b da Renata, capturado do payload da própria UI do Chatwoot).
// semEnvio = true quando NÃO há envio real: modo teste, canal 'teste', telefone de teste 5500000000xxx ou
// passo ENCERRAR (só muda o status). Nunca o nome da revendedora no texto (o banco já filtra; aqui de novo).

const CONFIG = {
  CHATWOOT_NIO_ACCOUNT: '195428',   // conta própria da Nio no Chatwoot (nunca a da Vero) — prompt 28, 07/11
};

const c = $input.first().json;
const modo = $('2 · Interruptor').first().json.modo;
const tel = String(c.telefone || '');
const texto = String(c.texto || '');

const PROIBIDO = new RegExp(['dh' + 'arma', 'gr[aá]tis', 'gratuit', 'combo', 'pacote', 'nio 5g', '2028', 'sem fidelidade'].join('|'), 'i');
let erro = null;
if (c.acao !== 'encerrar' && (!texto || PROIBIDO.test(texto) || texto.includes('*'))) erro = 'texto vazio ou reprovado no filtro de saída';

const semEnvio = c.acao === 'encerrar' || modo !== 'chatwoot' || c.canal === 'teste' || tel.startsWith('5500000000');

let corpo = null;
if (c.acao === 'texto') {
  corpo = { content: texto, message_type: 'outgoing', private: false };
} else if (c.acao === 'template') {
  const body = {};
  (c.params || []).forEach((v, i) => { body[String(i + 1)] = String(v); });
  corpo = {
    content: texto, message_type: 'outgoing', content_type: 'text',
    template_params: { name: c.template, category: c.categoria || 'MARKETING', language: 'pt_BR', processed_params: { body } },
  };
}

if (!semEnvio && !c.chatwoot_conversation_id) erro = erro || 'conversa sem chatwoot_conversation_id';
if (!semEnvio && !CONFIG.CHATWOOT_NIO_ACCOUNT) erro = erro || 'CHATWOOT_NIO_ACCOUNT vazio';

return [{ json: {
  conversaId: c.conversa_id,
  passo: c.proximo_passo,
  acao: c.acao,
  texto,
  excecao: c.excecao || null,
  semEnvio: semEnvio && !erro,
  erro,
  chatwootConversationId: c.chatwoot_conversation_id || null,
  corpo,
  config: CONFIG,
} }];

// NIOGEN | n8n/cadencia/c06_guard.js — nó "6h · Guard Chatwoot" do mari_cadencia (04/11/2026)
// Antes de QUALQUER envio real, relê a conversa no Chatwoot (padrão noF1 da Renata):
// humano atribuído, time atribuído, conversa resolvida ou etiqueta nao-contatar → para a escada (mari_cadencia_parar) e não envia.
// Sem resposta do Chatwoot (nó 6g desligado ou erro) → NÃO envia: vira falha (não queima o passo).
const m = $('5 · Montar envio').first().json;
const cw = $input.first().json || {};
const temDados = cw && (cw.id !== undefined || cw.status !== undefined) && !cw.conversaId;

if (!temDados) {
  return [{ json: { ...m, parar: false, enviar: false, ok: false, erro: 'guard do Chatwoot sem resposta (nó desligado ou erro) — não enviado' } }];
}
const humano = !!(cw.meta && cw.meta.assignee) || !!cw.assignee_id;
const time = !!cw.team_id || !!(cw.meta && cw.meta.team);
const resolvida = cw.status === 'resolved';
const naoContatar = Array.isArray(cw.labels) && cw.labels.includes('nao-contatar');   // adendo 2 (05/11): não tocar
const parar = humano || time || resolvida || naoContatar;
return [{ json: { ...m, parar, enviar: !parar, humano, time, resolvida, naoContatar } }];

// NIOGEN | n8n/cadencia/c07_resultado.js — nó "7r · Resultado" do mari_cadencia (04/11/2026)
// Lê a resposta do POST no Chatwoot: ok só com id da mensagem e status ≠ 'failed' (a Meta recusou).
// Nó 7 desligado → chega o próprio item montado (sem id) → falha registrada, passo não queima.
const g = $('6h · Guard Chatwoot').first().json;
const r = $input.first().json || {};
const ok = !!r.id && r.status !== 'failed' && !r.conversaId;
return [{ json: { ...g, ok, erro: ok ? null : (r.error || r.message || `chatwoot sem id (status=${r.status || 'nenhum'})`) } }];

// NIOGEN | n8n/cadencia/c09b_futuro_itens.js — nó "9b · Itens futuro" do mari_cadencia (07/11/2026, prompt 28)
// A RPC mari_futuro_pendentes (0052) devolve as conversas cuja venda está em Saída "Interesse futuro (com data)" e
// ainda sem a etiqueta/nota para essa data. Aqui só vira um item por conversa — sem decisão nenhuma.
// RPC com erro (ex.: 0052 ainda não aplicada) → nada a fazer nesta rodada (o ramo principal não é afetado).
const CHATWOOT_NIO_ACCOUNT = '195428';   // conta própria da Nio no Chatwoot (nunca a da Vero) — a mesma do c05
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.error || j.code || (j.message && !j.conversa_id)) continue;   // erro da RPC: pula
  const lista = Array.isArray(j) ? j : (j.conversa_id || j.mari_futuro_pendentes ? [j] : []);
  for (const x of lista) {
    const v = (x && x.mari_futuro_pendentes) || x;
    if (v && v.conversa_id && v.chatwoot_conversation_id && v.volta_em) {
      out.push({ json: { conta: CHATWOOT_NIO_ACCOUNT, conversaId: v.conversa_id, cw: String(v.chatwoot_conversation_id),
        voltaEm: v.volta_em, nota: v.nota } });
    }
  }
}
return out.slice(0, 20);

// NIOGEN | n8n/cadencia/c09d_futuro_etiquetas.js — nó "9d · Montar etiquetas" do mari_cadencia (07/11/2026, prompt 28)
// Recebe a conversa lida no Chatwoot (nó 9c) e monta a lista de etiquetas = as atuais + interesse-futuro.
// O POST /labels do Chatwoot SUBSTITUI a lista inteira — por isso a união. Sem resposta do Chatwoot → não mexe.
const ETIQUETA = 'interesse-futuro';
const out = [];
$input.all().forEach((it, i) => {
  const base = $('9b · Itens futuro').itemMatching(i).json;
  const cw = it.json || {};
  const leu = cw && (cw.id !== undefined || cw.status !== undefined) && !cw.conversaId;
  if (!leu) { out.push({ json: { ...base, ok: false, erro: 'Chatwoot sem resposta ao ler a conversa' } }); return; }
  const atuais = Array.isArray(cw.labels) ? cw.labels.map(String) : [];
  const labels = atuais.includes(ETIQUETA) ? atuais : [...atuais, ETIQUETA];
  out.push({ json: { ...base, ok: true, labels } });
});
return out;

// NIOGEN | n8n/cadencia/c09h_futuro_conferir.js — nó "9h · Conferir" do mari_cadencia (07/11/2026, prompt 28)
// Recebe a resposta da nota privada (nó 9g). Só marca a conversa (mari_futuro_marcar) quando a etiqueta (9f) e a
// nota (9g) voltaram ok — senão a próxima rodada tenta de novo. Falha vai para o log da execução, sem marcar.
const out = [];
$input.all().forEach((it, i) => {
  const base = $('9d · Montar etiquetas').itemMatching(i).json;
  const et = $('9f · Chatwoot etiquetas').itemMatching(i).json || {};
  const nota = it.json || {};
  const etOk = Array.isArray(et.payload) && et.payload.includes('interesse-futuro');
  const notaOk = !!nota.id && nota.private === true;
  out.push({ json: { ...base, marcar: etOk && notaOk,
    erro: etOk && notaOk ? null : `etiqueta ${etOk ? 'ok' : 'falhou'} · nota ${notaOk ? 'ok' : 'falhou'}` } });
});
return out;
